{
  "status": "SUPPORTED",
  "task_summary": "Identify components, fasten assembly, place tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "OBJECT",
        "function": "The assembly on the workbench that needs to be fastened.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": ["assembly", "fixture"],
        "required_properties": ["needs fastening"]
      },
      {
        "id": "compatible_component",
        "entity_kind": "OBJECT",
        "function": "The part required to complete the fastening.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": ["part", "hardware"],
        "required_properties": ["fits target"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The tool used to attach the component.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": ["screwdriver", "wrench"],
        "required_properties": ["usable"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the target sits and the tool is left.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": ["table"],
        "required_properties": []
      },
      {
        "id": "storage_container",
        "entity_kind": "FIXED_TARGET",
        "function": "The cabinet or drawer that may hold the component or tool.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": ["cabinet", "drawer"],
        "required_properties": ["contains items"]
      }
    ],
    "functional_relations": [
      {
        "id": "fits_into",
        "relation": "compatible_component fits into fastening_target",
        "participant_roles": ["compatible_component", "fastening_target"]
      ,
        "required": true
      },
      {
        "id": "attached_by",
        "relation": "fastening_tool is used to attach compatible_component to fastening_target",
        "participant_roles": ["fastening_tool", "compatible_component", "fastening_target"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "open_storage",
        "operation": "storage_container opens",
        "participant_roles": ["storage_container", "robot"],
        "operation_count": 1
      },
      {
        "id": "retrieve_component",
        "operation": "compatible_component moves from storage_container to fastening_target",
        "participant_roles": ["compatible_component", "storage_container", "fastening_target"],
        "operation_count": 1
      },
      {
        "id": "fasten",
        "operation": "fastening_tool joins compatible_component to fastening_target",
        "participant_roles": ["fastening_tool", "compatible_component", "fastening_target"],
        "operation_count": 1
      },
      {
        "id": "place_tool",
        "operation": "fastening_tool rests on workbench",
        "participant_roles": ["fastening_tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_target": [
        {"label": "yellow assembly on tray", "visual_description": "Yellow/grey object on black tray on table"}
      ],
      "compatible_component": [],
      "fastening_tool": [],
      "workbench": [
        {"label": "wooden table", "visual_description": "Wooden table with drawers and cabinet"}
      ],
      "storage_container": [
        {"label": "blue cabinet", "visual_description": "Blue cabinet with door"},
        {"label": "left drawer", "visual_description": "Left blue drawer under table"},
        {"label": "right drawer", "visual_description": "Right blue drawer under table"}
      ]
    },
    "inspectable_regions": [
      {"id": "storage_container", "label": "blue cabinet and drawers", "visual_description": "Closed storage structures", "reason": "Could contain the compatible_component or fastening_tool"}
    ],
    "inspection_order": ["storage_container", "workbench"]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
